function documentsRead(){
 try{const a=JSON.parse(localStorage.getItem(POCKET_DOCUMENTS_KEY)||'[]');return Array.isArray(a)?a.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.expires==='string'):[]}
 catch{return []}
}
function documentsWrite(items){
 try{localStorage.setItem(POCKET_DOCUMENTS_KEY,JSON.stringify(items));return true}
 catch{notify(learningLabel('Nu am putut salva documentele.','Could not save documents.'));return false}
}
function documentsDate(text){
 const t=shopVoiceFold(text),months=['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'];
 const m=t.match(/(?:^|\\s)(\\d{1,2})\\s+(ianuarie|februarie|martie|aprilie|mai|iunie|iulie|august|septembrie|octombrie|noiembrie|decembrie)(?:\\s+(\\d{4}))?(?=\\s|$|[,.!?])/);
 const numeric=t.match(/(?:^|\\s)(\\d{1,2})[./-](\\d{1,2})[./-](\\d{4})(?=\\s|$|[,.!?])/);
 if(!m&&!numeric)return null;
 const day=Number(m?m[1]:numeric[1]),month=m?months.indexOf(m[2]):Number(numeric[2])-1,year=Number((m?m[3]:numeric[3])||new Date().getFullYear()),d=new Date(year,month,day);
 return d.getFullYear()===year&&d.getMonth()===month&&d.getDate()===day?budgetISO(d):null;
}
function documentsParseVoice(raw){
 const date=documentsDate(raw);
 if(!date)return null;
 const t=shopVoiceFold(raw);
 let title=t.replace(/(?:^|\\s)\\d{1,2}\\s+(?:ianuarie|februarie|martie|aprilie|mai|iunie|iulie|august|septembrie|octombrie|noiembrie|decembrie)(?:\\s+\\d{4})?(?=\\s|$|[,.!?])/,' ')
  .replace(/(?:^|\\s)\\d{1,2}[./-]\\d{1,2}[./-]\\d{4}(?=\\s|$|[,.!?])/,' ')
  .replace(/^(?:adauga|inregistreaza|salveaza|noteaza|add|save)\\s+/,'')
  .replace(/\\b(?:documentul|actul|expira|valabil|pana|la|pe|data|de)\\b/g,' ').replace(/[,.!?;:]/g,' ').replace(/\\s+/g,' ').trim();
 if(title==='pasaportul'||title==='pasaport in'||title==='pasaport')title='pașaport';
 if(title==='permisul')title='permis';
 if(title==='buletinul')title='buletin';
 return title.length>=3?{title,expires:date}:null;
}
function documentsFind(query){
 const needle=shopVoiceFold(query).replace(/^(?:documentul|actul)\\s+/,'').trim();
 const canonical=value=>shopVoiceFold(value)
  .replace(/\\b(pasaportul|pasaport|pașaportul)\\b/gu,'pașaport')
  .replace(/\\b(permisul|permis)\\b/gu,'permis')
  .replace(/\\b(buletinul|buletin|cartea de identitate)\\b/gu,'identitate')
  .replace(/\\b(in|în|pe|la|de|documentul|actul|meu|mea)\\b/gu,' ').replace(/\\s+/g,' ').trim();
 const wanted=canonical(needle);
 const matches=documentsRead().filter(x=>{
  const name=canonical(x.title);
  return name===wanted||name.includes(wanted)||wanted.includes(name);
 });
 return matches.length===1?matches[0]:null;
}
function documentsSave(title,expires,id=null,type=null){
 title=String(title||'').trim().slice(0,100);
 const d=expires?new Date(String(expires)+'T12:00:00'):null;
 if(!title||(expires!==''&&(!/^\\d{4}-\\d{2}-\\d{2}$/.test(expires)||Number.isNaN(d.getTime())||budgetISO(d)!==expires))){
  notify(learningLabel('Introdu un nume și o dată validă.','Enter a name and valid date.'));return false;
 }
 const all=documentsRead(),i=all.findIndex(x=>x.id===id),now=new Date().toISOString();
 const item={id:i>=0?all[i].id:shopId(),title,expires,type:type|| (i>=0?all[i].type:documentsType(title)),createdAt:i>=0?all[i].createdAt:now,updatedAt:now,fields:i>=0?(all[i].fields||{}):{}};
 if(i>=0)all[i]=item;else all.push(item);
 if(!documentsWrite(all))return false;
 documentsSelectedId=null;documentsFilter=null;renderDocuments();
 notify(learningLabel('Document înregistrat.','Document saved.'));return true;
}
function documentsVoiceStop(){
 if(!documentsListening)return;
 documentsListening=false;
 if(pocketNativeVoiceAvailable())pocketNativeVoiceSend({action:'stopListen'});
}
function documentsVoiceStart(){
 if(documentsListening){documentsVoiceStop();return}
 if(!pocketNativeVoiceAvailable()){notify(learningLabel('Microfonul Android nu este disponibil.','Android microphone unavailable.'));return}
 documentsListening=true;
 const status=document.querySelector('.organize-voice-status');
 if(status)status.textContent=learningLabel('Te ascult…','Listening…');
 if(!pocketNativeVoiceSend({action:'listen',mode:'documents',language:shopVoiceLanguage()}))documentsVoiceStop();
}
function documentsVoiceHandleAndroid(data){
 if(data?.mode!=='documents')return false;
 if(!documentsListening)return true;
 if(data.status==='listening'||data.status==='partial'){
  const status=document.querySelector('.organize-voice-status');
  if(status)status.textContent=data.status==='partial'?String(data.text||''):learningLabel('Te ascult…','Listening…');
 }else if(data.status==='recognized'){documentsVoiceStop();documentsVoiceCommand(data.text)}
 else if(data.status==='error'){documentsVoiceStop();notify(learningLabel('Dictarea a fost întreruptă.','Dictation interrupted.'))}
 return true;
}
function documentsVoiceCommand(raw){
 const spoken=shopVoiceFold(raw);
 if(!spoken)return;
 const remove=spoken.match(/^(?:sterge|elimina|delete|remove)\\s+(?:documentul\\s+|actul\\s+)?(.+)$/);
 if(remove){
  const item=documentsFind(remove[1]);
  if(!item){notify(learningLabel('Documentul nu a fost identificat clar.','Document not uniquely identified.'));return}
  pocketConfirm(learningLabel('Ștergi documentul „','Delete document “')+item.title+'”?',()=>documentsDelete(item));return;
 }
 if(/^(?:ce|care|arata|afiseaza|show|which|what)\\b/.test(spoken)&&/\\b(?:documente|acte|expira|expirare|expiring|documents)\\b/.test(spoken)){
  documentsFilter=/luna|saptaman|decembrie|ianuarie|februarie|martie|aprilie|mai|iunie|iulie|august|septembrie|octombrie|noiembrie|next|week|month/.test(spoken)?budgetQueryPeriod(spoken):null;
  documentsSelectedId=null;renderDocuments();return;
 }
 const open=spoken.match(/^(?:arata|deschide|vezi|show|open)\\s+(?:documentul\\s+|actul\\s+)?(.+)$/);
 if(open){
  const item=documentsFind(open[1]);
  if(item){documentsSelectedId=item.id;documentsFilter=null;documentsEditing=false;renderDocuments()}
  else notify(learningLabel('Documentul nu a fost identificat clar.','Document not uniquely identified.'));
  return;
 }
 const parsed=documentsParseVoice(raw);
 if(parsed){documentsSave(parsed.title,parsed.expires);return}
 notify(learningLabel('Exemplu: „Pașaportul expiră pe 15 martie 2028”.','Example: “Passport expires 15 March 2028”.'));
}

/* Personal document images are stored as locally encoded JPEG Blobs in IndexedDB.
   This module never uploads documents to the chat, OCR endpoint or server. */
function documentsTypes(){
 const shared=[
  ['identity','Carte de identitate / ID','Identity card / ID'],
  ['passport','Pașaport','Passport'],
  ['licence','Permis de conducere','Driving licence'],
  ['vehicle','Carte identitate vehicul / V5C','Vehicle identity / V5C'],
  ['registration','Certificat înmatriculare','Vehicle registration'],
  ['inspection','ITP / MOT','Vehicle inspection / MOT'],
  ['insurance','Asigurare','Insurance'],
  ['nin','NIN / dovadă National Insurance','National Insurance proof'],
  ['other','Alt document','Other document']];
 // Region-dependent ordering; all types remain available to travellers.
 const region=String(typeof budgetDetectedCountry!=='undefined'?budgetDetectedCountry:'').toUpperCase();
 const priority=region==='GB'?['identity','passport','licence','nin','vehicle','inspection','registration','insurance','other']:
  ['identity','passport','licence','vehicle','registration','inspection','insurance','nin','other'];
 return priority.map(code=>shared.find(x=>x[0]===code));
}
function documentsType(title){
 const t=shopVoiceFold(title);
 if(/pasaport|passport/.test(t))return 'passport';
 if(/national insurance|nin\\b/.test(t))return 'nin';
 if(/permis|driving licen/.test(t))return 'licence';
 if(/itp\\b|mot\\b|inspectie|inspection/.test(t))return 'inspection';
 if(/asigurar|insurance|polita/.test(t))return 'insurance';
 if(/certificat.*inmatriculare|registration|talon/.test(t))return 'registration';
 if(/vehicul|v5c|vehicle|civ/.test(t))return 'vehicle';
 if(/identitate|buletin|identity|id card/.test(t))return 'identity';
 return 'other';
}
function documentsPhotoDB(){
 return new Promise((resolve,reject)=>{
  if(!window.indexedDB){reject(new Error('IndexedDB unavailable'));return}
  const req=indexedDB.open('mypocketai-private-documents',1);
  req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('images'))req.result.createObjectStore('images')};
  req.onsuccess=()=>resolve(req.result);
  req.onerror=()=>reject(req.error);
 });
}
async function documentsPhotoOperation(mode,key,value){
 const db=await documentsPhotoDB();
 try{return await new Promise((resolve,reject)=>{
  const tx=db.transaction('images',mode==='read'?'readonly':'readwrite');
  const store=tx.objectStore('images');
  const request=mode==='read'?store.get(key):mode==='delete'?store.delete(key):store.put(value,key);
  request.onsuccess=()=>resolve(request.result);
  request.onerror=()=>reject(request.error);
  tx.onerror=()=>reject(tx.error);
 })}finally{db.close()}
}
function documentsPhotoSlots(){
 return [['front',learningLabel('Față','Front')],['back',learningLabel('Verso','Back')],
  ['page3',learningLabel('Pagina 3','Page 3')],['page4',learningLabel('Pagina 4','Page 4')]];
}
async function documentsPhotoCompress(file){
 if(!file||!file.type.startsWith('image/')||file.size>15*1024*1024)throw new Error('invalid-image');
 const localURL=URL.createObjectURL(file);
 try{
  const img=new Image();
  await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=localURL});
  const scale=Math.min(1,1800/Math.max(img.naturalWidth,img.naturalHeight));
  const canvas=document.createElement('canvas');
  canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));
  canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));
  const ctx=canvas.getContext('2d');if(!ctx)throw new Error('canvas');
  ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);
  ctx.drawImage(img,0,0,canvas.width,canvas.height);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));
  canvas.width=0;canvas.height=0;
  if(!blob)throw new Error('encode');
  return blob;
 }finally{URL.revokeObjectURL(localURL)}
}
async function documentsPhotoScan(blob,id){
 const bridge=window.PocketAndroidDocumentScan;
 if(!bridge||typeof bridge.postMessage!=='function'){
  documentsScanWorking=false;
  notify(learningLabel('OCR disponibil doar în APK-ul actualizat. Fotografia a fost salvată; poți completa datele manual.','OCR requires the updated APK. Photo saved; enter the details manually.'));
  return;
 }
 try{
  const dataUrl=await new Promise((resolve,reject)=>{
   const reader=new FileReader();
   reader.onload=()=>resolve(String(reader.result||''));
   reader.onerror=()=>reject(new Error('read'));
   reader.readAsDataURL(blob);
  });
  const base64=dataUrl.slice(dataUrl.indexOf(',')+1);
  if(base64.length<32||base64.length>6_000_000)throw new Error('size');
  if(documentsSelectedId!==id)return;
  bridge.postMessage(JSON.stringify({action:'scan',id,base64}));
 }catch{
  documentsScanWorking=false;
  if(documentsSelectedId===id)renderDocuments();
  notify(learningLabel('Nu am putut transmite fotografia către OCR. Fotografia rămâne salvată.','Could not send photo to OCR. The photo remains saved.'));
 }
}
async function documentsPhotoSave(id,slot,file){
 try{
  const blob=await documentsPhotoCompress(file);
  await documentsPhotoOperation('put',id+':'+slot,blob);
  if(documentsSelectedId===id){
   documentsScanDraft=null;documentsScanWorking=true;renderDocuments();
   documentsPhotoScan(blob,id);
  }
  notify(learningLabel('Fotografia a fost salvată local.','Photo saved locally.'));
 }catch{
  documentsScanWorking=false;
  notify(learningLabel('Fotografia nu a putut fi salvată. Încearcă un JPG/PNG mai mic.','Could not save photo. Try a smaller JPG/PNG.'));
 }
}
async function documentsPhotoDeleteAll(id){
 try{for(const [slot] of documentsPhotoSlots())await documentsPhotoOperation('delete',id+':'+slot)}
 catch{notify(learningLabel('Nu s-au putut elimina toate fotografiile locale.','Some locally stored photos could not be removed.'))}
}
function documentsDelete(item){
 if(!documentsWrite(documentsRead().filter(x=>x.id!==item.id)))return;
 documentsPhotoDeleteAll(item.id);
 documentsSelectedId=null;documentsEditing=false;renderDocuments();
}
async function documentsOpenPhoto(id,slot){
 let blob;
 try{blob=await documentsPhotoOperation('read',id+':'+slot)}catch{}
 if(!blob){notify(learningLabel('Fotografia nu este disponibilă pe acest dispozitiv.','Photo unavailable on this device.'));return}
 const url=URL.createObjectURL(blob);
 const modal=document.createElement('dialog');modal.className='document-photo-fullscreen';
 modal.setAttribute('aria-label',learningLabel('Fotografie document','Document photograph'));
 const close=document.createElement('button');close.type='button';close.className='document-photo-close';
 close.textContent='✕ '+learningLabel('Închide','Close');close.onclick=()=>modal.close();
 const img=document.createElement('img');img.src=url;img.alt=learningLabel('Fotografia documentului','Document photo');
 modal.append(close,img);
 modal.addEventListener('close',()=>{URL.revokeObjectURL(url);modal.remove()},{once:true});
 document.body.append(modal);modal.showModal();
}
function documentsPhotoGallery(id,host){
 const grid=budgetNode('div','documents-photo-grid');
 for(const [slot,label] of documentsPhotoSlots()){
  const area=budgetNode('div','documents-photo-tile');
  const preview=budgetNode('button','documents-photo-preview');
  preview.type='button';preview.textContent='📷 '+label;
  preview.setAttribute('aria-label',learningLabel('Deschide fotografia ','Open photo ')+label);
  preview.onclick=()=>documentsOpenPhoto(id,slot);
  const file=document.createElement('input');file.type='file';file.accept='image/*';
  file.className='documents-photo-file';file.hidden=true;
  file.onchange=async()=>{if(file.files?.[0])await documentsPhotoSave(id,slot,file.files[0]);file.value=''};
  const add=budgetButton(learningLabel('Adaugă / scanează','Add / scan'),()=>file.click(),'secondary-btn');
  area.append(preview,add,file);grid.append(area);
  documentsPhotoOperation('read',id+':'+slot).then(blob=>{
   if(!blob||!preview.isConnected)return;
   const url=URL.createObjectURL(blob);
   const image=document.createElement('img');image.src=url;image.alt=label;
   image.onload=()=>URL.revokeObjectURL(url);
   image.onerror=()=>URL.revokeObjectURL(url);
   preview.replaceChildren(image);
  }).catch(()=>{});
 }
 host.append(grid);
}



/* Only user-approved OCR data is stored. No document image or text leaves the device. */
function documentsScanExtract(raw,geometry=[]){
 // Keep local text in memory only. Never infer a missing value from a label.
 const rawLines=String(raw||'').slice(0,16000).split(/\\r?\\n/).map(v=>v.trim()).filter(Boolean);
 const layout=Array.isArray(geometry)?geometry.slice(0,150):[];
 const rows=layout.length?layout.filter(v=>v&&typeof v.text==='string').map(v=>({
  text:v.text.trim(),left:Number(v.left),right:Number(v.right),
  top:Number(v.top),bottom:Number(v.bottom)
 })).filter(v=>v.text):rawLines.map(text=>({text}));
 const normalized=value=>String(value||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')
  .replace(/ø/gi,'o').replace(/æ/gi,'ae').replace(/œ/gi,'oe').toLowerCase()
  .replace(/[\\/|:;,()]+/g,' ').replace(/\\s+/g,' ').trim();
 const aliases={
  number:['passport number','passport no','passport nr','passport number no','pasnummer','pas nr','pas no','passnummer','document number','document no','numar document','numarul documentului','serie si numar','numero du passeport','numero de passeport','numero de pasaporte','registration number','driving licence number'],
  holder:['surname','surnames','last name','family name','nom','nom de famille','efternavn','familienname','nachname','cognome','apellido','apellidos','nume de familie','nume'],
  given:['given name','given names','first name','first names','fornavn','fornavne','prenom','prenoms','prename','vornamen','vorname','prenume','nombre','nombres','nome proprio'],
  birth:['date of birth','birth date','date de naissance','dato de naissance','fodselsdato','geburtsdatum','data nasterii','fecha de nacimiento','date of born'],
  issued:['date of issue','issue date','date de delivrance','udstedelsesdato','udstedt den','ausstellungsdatum','data emiterii','fecha de expedicion','issued on'],
  expires:['date of expiry','expiry date','expiration date','date dexpiration','date de expiration','udlobsdato','gyldig til','ablaufdatum','data expirarii','valabil pana la','fecha de caducidad','valid until','valid to','expires on'],
  country:['issuing country','country of issue','pays emetteur','udstedende land','tara emitenta'],
  issuer:['issuing authority','authority','autoritatea emitenta','autoritate emitenta','issued by','autorite de delivrance','udstedende myndighed']
 };
 const allAliases=Object.entries(aliases).flatMap(([key,words])=>words.map(word=>({key,word})))
  .sort((a,b)=>b.word.length-a.word.length);
 const whichLabel=text=>{
  const n=' '+normalized(text)+' ';
  const matched=new Set();
  for(const {key,word} of allAliases)if(n.includes(' '+word+' '))matched.add(key);
  return matched.size===1?[...matched][0]:null;
 };
 const months={jan:1,january:1,januar:1,janvier:1,feb:2,february:2,februar:2,fevrier:2,
  mar:3,march:3,marts:3,mars:3,apr:4,april:4,avr:4,may:5,mai:5,maj:5,mayo:5,
  jun:6,june:6,juni:6,juin:6,jul:7,july:7,juli:7,juillet:7,aug:8,august:8,aout:8,
  sep:9,sept:9,september:9,septembre:9,oct:10,okt:10,october:10,oktober:10,octobre:10,
  nov:11,november:11,novembre:11,dec:12,december:12,dezember:12,decembre:12};
 const validISO=(year,month,day)=>{
  if(year<1900||year>2100)return '';
  const iso=[year,String(month).padStart(2,'0'),String(day).padStart(2,'0')].join('-');
  const d=new Date(iso+'T12:00:00');
  return Number.isNaN(d.getTime())||budgetISO(d)!==iso?'':iso;
 };
 const parseDate=text=>{
  const t=normalized(text);
  let m=t.match(/\\b(\\d{4})[./-](\\d{1,2})[./-](\\d{1,2})\\b/);
  if(m)return validISO(Number(m[1]),Number(m[2]),Number(m[3]));
  m=t.match(/\\b(\\d{1,2})[./-](\\d{1,2})[./-](\\d{4})\\b/);
  if(m)return validISO(Number(m[3]),Number(m[2]),Number(m[1]));
  m=t.match(/\\b(\\d{1,2})[. ]+([a-z]+)[. ,]+(\\d{4})\\b/);
  return m&&months[m[2]]?validISO(Number(m[3]),months[m[2]],Number(m[1])):'';
 };
 const fields={};
 const usedRows=new Set(); // One OCR value line cannot supply two identity fields.
 const labelRows=rows.map((r,i)=>({i,key:whichLabel(r.text),r})).filter(x=>x.key);
 const isLabel=text=>whichLabel(text)!==null;
 const check=(key,value)=>{
  const t=String(value||'').trim();
  if(!t||t.length>100||isLabel(t))return '';
  if(['issued','expires','birth'].includes(key))return parseDate(t);
  if(key==='number')return /^[A-Z0-9][A-Z0-9 -]{3,30}$/i.test(t)&&/\\d/.test(t)?t:'';
  if(key==='holder'||key==='given')return /^[\\p{L}][\\p{L}' -]{1,65}$/u.test(t) && t.split(/\\s+/).length<=5?t:'';
  return /^[\\p{L}0-9][\\p{L}0-9 ,'.()/-]{1,99}$/u.test(t)?t:'';
 };
 for(let i=0;i<rows.length;i++){
  const row=rows[i],key=whichLabel(row.text);
  if(!key||fields[key])continue;
  let candidate='';
  // Same-line values require an explicit delimiter, not a multilingual slash.
  const inline=row.text.match(/:\\s*(.+)$/);
  if(inline)candidate=check(key,inline[1]);
  if(!candidate&&Number.isFinite(row.top)&&Number.isFinite(row.bottom)){
   const h=Math.max(12,row.bottom-row.top),maxBelow=Math.max(145,h*7);
   const nearby=[];
   for(let j=0;j<rows.length;j++){
    if(j===i||usedRows.has(j))continue;
    const other=rows[j];
    if(!Number.isFinite(other.top)||!Number.isFinite(other.left)||isLabel(other.text))continue;
    const dy=other.top-row.bottom;
    if(dy< -h*.5||dy>maxBelow)continue;
    const rightOf=other.left>=row.right&&Math.abs(other.top-row.top)<=h*1.5;
    const aligned=other.right>=row.left-h*2&&other.left<=row.right+Math.max(140,h*10);
    if(!rightOf&&!aligned)continue;
    // Never jump across another field caption to borrow its value.
    if(!rightOf && labelRows.some(label=>label.i!==i &&
      Number.isFinite(label.r.top) && label.r.top>row.bottom-h*.3 && label.r.top<other.top &&
      label.r.right>=Math.min(row.left,other.left)-h &&
      label.r.left<=Math.max(row.right,other.right)+h))continue;
    const val=check(key,other.text);
    if(!val)continue;
    const distance=rightOf?(other.left-row.right)*.2+Math.abs(other.top-row.top)*.4:
      Math.max(0,dy)+Math.abs(other.left-row.left)*.45;
    nearby.push({val,distance,j});
   }
   nearby.sort((a,b)=>a.distance-b.distance);
   candidate=nearby[0]?.val||'';
   if(candidate)usedRows.add(nearby[0].j);
  }
  if(!candidate && !layout.length){
   // Without coordinates, only use the next unclaimed value before another caption.
   for(let j=i+1;j<Math.min(rows.length,i+3);j++){
    if(isLabel(rows[j].text))break;
    if(usedRows.has(j))continue;
    candidate=check(key,rows[j].text);
    if(candidate){usedRows.add(j);break}
   }
  }
  if(candidate)fields[key]=candidate;
 }
 // ICAO TD3 passports: require validated number and expiry check digits.
 const clean=value=>String(value).toUpperCase().replace(/[«‹〈]/g,'<')
  .replace(/\\s/g,'').replace(/[^A-Z0-9<]/g,'');
 const mrz=rawLines.map(clean);
 const weights=[7,3,1];
 const digit=value=>{
  let sum=0;
  for(let i=0;i<value.length;i++){
   const c=value[i],n=c==='<'?0:/[0-9]/.test(c)?Number(c):c.charCodeAt(0)-55;
   if(n<0||n>35)return '?';
   sum+=n*weights[i%3];
  }
  return String(sum%10);
 };
 for(let j=0;j<mrz.length-1;j++){
  const a=mrz[j],b=mrz[j+1];
  if(a.length!==44||b.length!==44||!a.startsWith('P<'))continue;
  if(digit(b.slice(0,9))!==b[9]||digit(b.slice(21,27))!==b[27])continue;
  const passportNo=b.slice(0,9).replace(/<+$/,'');
  if(passportNo)fields.number=passportNo;
  const expiry=validISO(2000+Number(b.slice(21,23)),Number(b.slice(23,25)),Number(b.slice(25,27)));
  if(expiry)fields.expires=expiry;
  if(digit(b.slice(13,19))===b[19]){
   const yy=Number(b.slice(13,15)),year=yy>(new Date().getFullYear()%100)?1900+yy:2000+yy;
   const birth=validISO(year,Number(b.slice(15,17)),Number(b.slice(17,19)));
   if(birth)fields.birth=birth;
  }
  if(!fields.country)fields.country=a.slice(2,5); // Issuing country, not nationality.
  const name=a.slice(5).split('<<');
  if(name[0])fields.holder=name[0].replace(/<+/g,' ').trim();
  if(name[1])fields.given=name.slice(1).join(' ').replace(/<+/g,' ').trim();
  break;
 }
 // ICAO TD1 identity cards (3 lines of 30): do not guess from partial MRZ.
 for(let j=0;j<mrz.length-2;j++){
  const a=mrz[j],b=mrz[j+1],c=mrz[j+2];
  if(a.length!==30||b.length!==30||c.length!==30||!/^[IAC][A-Z<]/.test(a))continue;
  if(digit(a.slice(5,14))!==a[14] ||
     digit(b.slice(0,6))!==b[6] ||
     digit(b.slice(8,14))!==b[14])continue;
  const cardNo=a.slice(5,14).replace(/<+$/,'');
  if(cardNo)fields.number=cardNo;
  const birthCode=b.slice(0,6);
  const yy=Number(birthCode.slice(0,2));
  const year=yy>(new Date().getFullYear()%100)?1900+yy:2000+yy;
  const birth=validISO(year,Number(birthCode.slice(2,4)),Number(birthCode.slice(4,6)));
  if(birth)fields.birth=birth;
  const expiration=validISO(2000+Number(b.slice(8,10)),Number(b.slice(10,12)),Number(b.slice(12,14)));
  if(expiration)fields.expires=expiration;
  fields.country=a.slice(2,5);
  const names=c.split('<<');
  if(names.length>1&&names[0])fields.holder=names[0].replace(/<+/g,' ').trim();
  if(names.length>1&&names[1])fields.given=names.slice(1).join(' ').replace(/<+/g,' ').trim();
  break;
 }
 // Do not silently prefill two different identity fields with the same OCR
 // text. A genuine same-name case can still be entered manually after review.
 if(fields.holder&&fields.given&&normalized(fields.holder)===normalized(fields.given)){
  delete fields.given;
 }
 return fields;
}
