const POCKET_TASKS_KEY='mypocketai.tasks.v1';
let tasksSection='home',tasksListening=false,tasksRecognition=null;
function tasksRead(){
 try{
  const data=JSON.parse(localStorage.getItem(POCKET_TASKS_KEY)||'[]');
  return Array.isArray(data)?data.filter(t=>t&&typeof t.title==='string'&&typeof t.id==='string'):[];
 }catch{return []}
}
function tasksWrite(items){
 try{localStorage.setItem(POCKET_TASKS_KEY,JSON.stringify(items));return true}
 catch{notify(learningLabel('Nu am putut salva sarcinile.','Could not save tasks.'));return false}
}
function tasksDueLabel(value){
 if(!value)return learningLabel('Fără termen','No deadline');
 const date=new Date(value+'T12:00:00');
 return Number.isNaN(date.getTime())?value:date.toLocaleDateString(state.language==='ro'?'ro-RO':'en-GB');
}
function tasksParseSpokenDeadline(value,now=new Date()){
 const original=String(value||'').replace(/\\s+/g,' ').trim();
 let title=original,due='',time='';
 const normalized=shopVoiceFold(original);
 const dateWord=normalized.match(/(?:^|\\s)(poimaine|maine|astazi|azi)(?=\\s|$|[,.;:])/u);
 if(!dateWord){
  const months=['ianuarie','februarie','martie','aprilie','mai','iunie','iulie','august','septembrie','octombrie','noiembrie','decembrie'];
  const match=original.match(/(?:^|[\\s,])(\\d{1,2})\\s+(ianuarie|februarie|martie|aprilie|mai|iunie|iulie|august|septembrie|octombrie|noiembrie|decembrie)(?:\\s+(\\d{4}))?(?=$|[\\s,.;])/iu);
  if(!match)return {title,due,time};
  const day=Number(match[1]),month=months.indexOf(match[2].toLowerCase()),year=Number(match[3]||now.getFullYear());
  const date=new Date(year,month,day);
  if(date.getFullYear()!==year||date.getMonth()!==month||date.getDate()!==day)return {title,due,time};
  due=[year,String(month+1).padStart(2,'0'),String(day).padStart(2,'0')].join('-');
  let working=original.replace(match[0],' ');
  const clock=working.match(/(?:^|[\\s,])(?:la\\s+)?ora\\s+(\\d{1,2})(?:[:.](\\d{2}))?(?=$|[\\s,.;])/iu);
  if(clock){
   const hour=Number(clock[1]),minute=Number(clock[2]||0);
   if(hour>23||minute>59)return {title:original,due:'',time:''};
   time=String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');
   working=working.replace(clock[0],' ');
  }
  title=working.replace(/^[\\s,.;:]+|[\\s,.;:]+$/gu,'').replace(/\\s+/g,' ').trim();
  if(!title)return {title:original,due:'',time:''};
  return {title,due,time};
 }
 const dateIndex=dateWord.index+(dateWord[0].startsWith(' ')?1:0);
 const dateLength=dateWord[1].length;
 // The folded version retains character positions for Romanian accented forms only
 // when combining marks have been removed; locate the corresponding word in source.
 const words=[...original.matchAll(/\\S+/gu)];
 const corresponding=words.find(w=>shopVoiceFold(w[0].replace(/^[^\\p{L}]+|[^\\p{L}]+$/gu,''))===dateWord[1] && Math.abs(w.index-dateIndex)<4);
 if(!corresponding)return {title,due,time};
 const d=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 if(dateWord[1]==='maine')d.setDate(d.getDate()+1);
 if(dateWord[1]==='poimaine')d.setDate(d.getDate()+2);
 const datePart=corresponding[0];
 const prefix=original.slice(0,corresponding.index);
 const suffix=original.slice(corresponding.index+datePart.length);
 const withoutDate=(prefix+' '+suffix).replace(/\\s+/g,' ').trim();
 // Only consume an hour when explicitly marked ("ora 10", "la 10", "10:30").
 const timeRe=/(?:^|[\\s,])(?:(?:la\\s+)?ora\\s+|la\\s+)(\\d{1,2})(?:[:.](\\d{2}))?(?=\\s|$|[,.;])|(?:^|[\\s,])(\\d{1,2})[:.](\\d{2})(?=\\s|$|[,.;])/iu;
 const timeMatch=withoutDate.match(timeRe);
 if(timeMatch){
  const h=Number(timeMatch[1]??timeMatch[3]),m=Number(timeMatch[2]??timeMatch[4]??0);
  if(h>23||m>59)return {title:original,due:'',time:''};
  time=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');
 }
 title=(timeMatch?withoutDate.replace(timeMatch[0],' '):withoutDate)
  .replace(/^(?:pe|pentru|la|în|in)\\s+/iu,'')
  .replace(/\\s+(?:pe|pentru|la|în|in)$/iu,'')
  .replace(/^[\\s,.;:]+|[\\s,.;:]+$/gu,'').replace(/\\s+/g,' ').trim();
 if(!title||/^(?:ora|la|sarcina|obiectiv)$/iu.test(shopVoiceFold(title)))return {title:original,due:'',time:''};
 due=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
 return {title,due,time};
}
function tasksRepairLegacyVoiceDates(){
 const all=tasksRead();let changed=false;
 for(const task of all){
  if(task.source!=='voice'||task.due)continue;
  const created=new Date(task.createdAt);if(Number.isNaN(created.getTime()))continue;
  const parsed=tasksParseSpokenDeadline(task.title,created);
  if(!parsed.due||parsed.title===task.title)continue;
  task.title=parsed.title;task.due=parsed.due;task.time=parsed.time;changed=true;
 }
 if(changed&&tasksWrite(all))for(const task of all)if(task.source==='voice'&&task.due)tasksToAgenda(task,true);
}
function tasksCreate(title,goal=false,due='',priority='normal',fromVoice=false,time=''){
 title=String(title||'').trim();if(!title||!/[\\p{L}\\p{N}]/u.test(title))return false;
 const data=tasksRead(),item={id:shopId(),title:title.slice(0,140),goal,priority,due,time,source:fromVoice?'voice':'manual',done:false,archived:false,createdAt:new Date().toISOString()};
 data.push(item);
 if(!tasksWrite(data))return false;
 if(fromVoice&&due)tasksToAgenda(item,true);
 return true;
}
function tasksUpdate(id,update){const data=tasksRead(),i=data.findIndex(t=>t.id===id);if(i<0)return false;data[i]={...data[i],...update};return tasksWrite(data)}
function tasksDelete(id){const data=tasksRead();return tasksWrite(data.filter(t=>t.id!==id))}
function tasksToAgenda(item,automatic=false){
 if(!item.due){if(!automatic)notify(learningLabel('Stabilește un termen pentru a trimite sarcina în Agendă.','Set a deadline to add this task to the agenda.'));return false}
 const events=agendaRead();
 const hasTime=/^(?:[01]\\d|2[0-3]):[0-5]\\d$/.test(item.time||'');
 const when=new Date(item.due+'T'+(hasTime?item.time+':00':'12:00:00'));
 if(Number.isNaN(when.getTime()))return false;
 const previous=events.findIndex(e=>e.linkedTaskId===item.id);
 const event={
  ...(previous>=0?events[previous]:{}),
  id:previous>=0?events[previous].id:shopId(),
  title:item.title,kind:'task',allDay:!hasTime,linkedTaskId:item.id,
  when:when.toISOString(),reminderPreset:'default',
  createdAt:previous>=0?events[previous].createdAt:new Date().toISOString()
 };
 if(previous>=0){
  const existing=events[previous];
  if(existing.title===event.title&&existing.when===event.when&&existing.allDay===event.allDay)return true;
  events[previous]=event;
 }else events.push(event);
 const ok=agendaWrite(events);
 if(!ok)return false;
 if(!automatic)notify(hasTime?learningLabel('Sarcina a fost sincronizată în Agendă cu ora specificată.','Task synchronized with agenda at the specified time.'):learningLabel('Sarcina a fost sincronizată în Agendă fără oră.','Task synchronized with agenda without a time.'));
 return true;
}
function tasksVoiceStatus(message){
 const status=document.querySelector('.tasks-voice-status');
 if(status)status.textContent=message||'';
 const mic=document.querySelector('.tasks-toolbar .tasks-dictation');
 if(mic){mic.setAttribute('aria-pressed',tasksListening?'true':'false');mic.classList.toggle('is-listening',tasksListening)}
}
function tasksVoiceStop(){
 tasksListening=false;
 if(pocketNativeVoiceAvailable())pocketNativeVoiceSend({action:'stopListen'});
 if(tasksRecognition){try{tasksRecognition.onresult=null;tasksRecognition.onerror=null;tasksRecognition.onend=null;tasksRecognition.abort()}catch{}tasksRecognition=null}
 tasksVoiceStatus('');
}
function tasksVoiceFinish(phrase){
 if(!tasksListening)return;
 tasksVoiceStop();
 if(String(phrase||'').trim())tasksVoiceCommand(phrase);
 else notify(learningLabel('Nu am auzit o comandă. Încearcă din nou.','No command heard. Please try again.'));
}
function tasksVoiceHandleAndroid(data){
 if(data?.mode!=='tasks')return false;
 if(!tasksListening)return true;
 if(data.status==='listening'){tasksVoiceStatus(learningLabel('Te ascult…','Listening…'));return true}
 if(data.status==='partial'){tasksVoiceStatus(learningLabel('Aud: ','Hearing: ')+String(data.text||''));return true}
 if(data.status==='recognized'){tasksVoiceFinish(String(data.text||''));return true}
 if(data.status==='error'){tasksVoiceStop();notify(learningLabel('Microfonul Android a fost întrerupt. Încearcă din nou.','Android microphone stopped. Try again.'));return true}
 return true;
}
function tasksVoiceCommand(phrase){
 const spoken=String(phrase||'').trim();const norm=shopVoiceFold(spoken);
 if(!norm)return;
 if(/^(?:arata|afiseaza|deschide) (?:obiective|obiectivele)/.test(norm)){tasksSection='goals';renderTasks();return}
 if(/^(?:arata|afiseaza|deschide) (?:arhiva|finalizate)/.test(norm)){tasksSection='archive';renderTasks();return}
 const action=norm.match(/^(bifeaza|finalizeaza|arhiveaza|sterge) (?:sarcina |obiectivul )?(.+)$/);
 if(action){
  const found=tasksRead().filter(t=>shopVoiceFold(t.title)===action[2]||shopVoiceFold(t.title).includes(action[2]));
  if(found.length!==1){notify(learningLabel('Nu am identificat o singură sarcină.','Could not identify one unique task.'));return}
  if(action[1]==='sterge'){tasksConfirmDelete(found[0]);return}
  tasksUpdate(found[0].id,action[1]==='arhiveaza'?{archived:true}:{done:true});renderTasks();return;
 }
 const add=spoken.replace(/[,;]+/g,' ').replace(/\\s+/g,' ').trim().match(/^(?:adaug[aă]|ad[aă]uga|creeaz[aă]|noteaz[aă]|trece)\\s+(?:(?:(?:un|o)\\s+)?(?:obiectiv|sarcin[aă])\\s*)?(.+)$/i);
 if(add){
  let title=add[1].trim();const goal=/obiectiv/i.test(spoken.slice(0,spoken.length-title.length));
  const priority=/prioritate (?:mare|ridicata|ridicată)/i.test(title)?'high':'normal';
  title=title.replace(/[, ]*prioritate (?:mare|ridicata|ridicată)/i,'').trim();
  const parsed=tasksParseSpokenDeadline(title);
  if(tasksCreate(parsed.title,goal,parsed.due,priority,true,parsed.time)){tasksSection=goal?'goals':'items';renderTasks();if(goal)tasksSuggestGoal(parsed.title)}
  return;
 }
 // A natural date-first phrase is a valid task command even without "Adaugă".
 const spokenTask=tasksParseSpokenDeadline(spoken);
 if(spokenTask.due&&spokenTask.title!==spoken){
  if(tasksCreate(spokenTask.title,false,spokenTask.due,'normal',true,spokenTask.time)){tasksSection='items';renderTasks()}
  return;
 }
 notify(learningLabel('Spune „Adaugă sarcină...” sau „Bifează...”.','Say “Add task...” or “Complete...”.'));
}
function tasksVoiceStart(){
 if(tasksListening){tasksVoiceStop();return}
 if(state.speaking){notify(learningLabel('Încheie mai întâi redarea vocală.','Finish voice playback first.'));return}
 if(!pocketNativeVoiceAvailable()){notify(learningLabel('Microfonul Android nu este disponibil.','Android microphone unavailable.'));return}
 tasksListening=true;
 tasksVoiceStatus(learningLabel('Microfon activ — vorbește acum…','Microphone active — speak now…'));
 if(!pocketNativeVoiceSend({action:'listen',mode:'tasks',language:shopVoiceLanguage()})){
  tasksVoiceStop();notify(learningLabel('Nu am putut porni microfonul Android.','Unable to start Android microphone.'));
 }
}
function tasksConfirmDelete(item){
 pocketConfirm(learningLabel('Ștergi definitiv: ','Permanently delete: ')+item.title+'?',()=>{if(tasksDelete(item.id))renderTasks()});
}
async function tasksSuggestGoal(title){
 const panel=document.querySelector('.tasks-ai-suggestions');
 if(!panel||tasksSection!=='goals')return;
 panel.replaceChildren();
 const heading=document.createElement('strong');heading.textContent=learningLabel('Sugestii Pocket AI pentru: ','Pocket AI suggestions for: ')+title;
 const body=document.createElement('p');body.textContent=learningLabel('Pregătesc pașii recomandați…','Preparing suggested steps…');
 panel.append(heading,body);
 try{
  const message=state.language==='ro'
   ?'Pentru obiectivul personal „'+title+'”, recomandă 3 până la 5 pași practici, numerotați, în limba română. Nu inventa costuri, date, rezervări sau sarcini deja executate. Răspunde doar cu pașii, concis.'
   :'Suggest 3 to 5 practical numbered steps for the personal goal "'+title+'". Do not invent costs, dates, bookings or completed actions. Respond only with concise steps.';
  const response=await fetch(CLIENT_CONFIG.apiUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,language:state.language,module:'assistant',history:[]})});
  const data=await response.json();
  if(!response.ok||data.status!=='success'||typeof data.reply!=='string'||!data.reply.trim())throw new Error();
  if(panel.isConnected&&tasksSection==='goals')body.textContent=data.reply.trim().slice(0,1800);
 }catch{
  if(panel.isConnected&&tasksSection==='goals')body.textContent=learningLabel('Sugestiile AI nu sunt disponibile acum. Obiectivul rămâne salvat.','AI suggestions are unavailable. Your goal remains saved.');
 }
}
