 return String(text||'').replace(/[\\p{L}]+/gu,word=>{
  const corrected=words[shopVoiceFold(word)];
  return corrected?(word[0]===word[0].toLocaleUpperCase()?corrected[0].toLocaleUpperCase()+corrected.slice(1):corrected):word;
 }).normalize('NFC');
