 const via=(route.via||[]).filter(p=>Number.isFinite(p.latitude)&&Number.isFinite(p.longitude)).slice(0,3);if(via.length)u.searchParams.set('waypoints',via.map(p=>p.latitude+','+p.longitude).join('|'));
